  public var STATE_TRANSITION: FlatbufferVector<Double> { return _accessor.vector(at: VT.STATE_TRANSITION, byteSize: 8) }
  public func withUnsafePointerToStateTransition<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.STATE_TRANSITION, body: body) }
  ///  Jacobi constant of the trajectory (conserved in the CR3BP).
  public var JACOBI: Double { let o = _accessor.offset(VT.JACOBI); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public static func starttbpTrajectory(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 7) }
  public static func add(DIMENSIONAL: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: DIMENSIONAL, def: false,
   at: VT.DIMENSIONAL) }
  public static func add(FRAME: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: FRAME, at: VT.FRAME) }
  public static func add(EPOCH_MS: Int64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: EPOCH_MS, def: 0, at: VT.EPOCH_MS) }
  public static func addVectorOf(TIMES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TIMES, at: VT.TIMES) }
  public static func addVectorOf(STATES: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: STATES, at: VT.STATES) }
  public static func addVectorOf(STATE_TRANSITION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: STATE_TRANSITION, at: VT.STATE_TRANSITION) }
  public static func add(JACOBI: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: JACOBI, def: 0.0, at: VT.JACOBI) }
  public static func endtbpTrajectory(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createtbpTrajectory(
    _ fbb: inout FlatBufferBuilder,
    DIMENSIONAL: Bool = false,
    FRAMEOffset FRAME: Offset = Offset(),
    EPOCH_MS: Int64 = 0,
    TIMESVectorOffset TIMES: Offset = Offset(),
    STATESVectorOffset STATES: Offset = Offset(),
    STATE_TRANSITIONVectorOffset STATE_TRANSITION: Offset = Offset(),
    JACOBI: Double = 0.0
  ) -> Offset {
    let __start = tbpTrajectory.starttbpTrajectory(&fbb)
    tbpTrajectory.add(DIMENSIONAL: DIMENSIONAL, &fbb)
    tbpTrajectory.add(FRAME: FRAME, &fbb)
    tbpTrajectory.add(EPOCH_MS: EPOCH_MS, &fbb)
    tbpTrajectory.addVectorOf(TIMES: TIMES, &fbb)
    tbpTrajectory.addVectorOf(STATES: STATES, &fbb)
    tbpTrajectory.addVectorOf(STATE_TRANSITION: STATE_TRANSITION, &fbb)
    tbpTrajectory.add(JACOBI: JACOBI, &fbb)
    return tbpTrajectory.endtbpTrajectory(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.DIMENSIONAL, fieldName: "DIMENSIONAL", required: false, type: Bool.self)
    try _v.visit(field: VT.FRAME, fieldName: "FRAME", required: false, type: ForwardOffset<RFM>.self)
    try _v.visit(field: VT.EPOCH_MS, fieldName: "EPOCH_MS", required: false, type: Int64.self)
    try _v.visit(field: VT.TIMES, fieldName: "TIMES", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STATES, fieldName: "STATES", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STATE_TRANSITION, fieldName: "STATE_TRANSITION", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.JACOBI, fieldName: "JACOBI", required: false, type: Double.self)
    _v.finish()
  }
}

///  One libration point and its linear stability.
public struct tbpLibrationPoint: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$TBP" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: tbpLibrationPoint.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let POINT: VOffset = 4
    static let X: VOffset = 6
    static let Y: VOffset = 8
    static let Z: VOffset = 10
    static let JACOBI: VOffset = 12
    static let EIGENVALUES_REAL: VOffset = 14
    static let EIGENVALUES_IMAGINARY: VOffset = 16
    static let STABLE: VOffset = 18
  }

  public var POINT: rfmLibrationPoint { let o = _accessor.offset(VT.POINT); return o == 0 ? .unspecified : rfmLibrationPoint(rawValue: _accessor.readBuffer(of: UInt8.self, at: o)) ?? .unspecified }
  ///  Synodic position, non-dimensional.
  public var X: Double { let o = _accessor.offset(VT.X); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var Y: Double { let o = _accessor.offset(VT.Y); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var Z: Double { let o = _accessor.offset(VT.Z); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Jacobi constant at the point.
  public var JACOBI: Double { let o = _accessor.offset(VT.JACOBI); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  ///  Eigenvalues of the linearised dynamics at the point (6 each); empty =
  ///  not computed.
  public var EIGENVALUES_REAL: FlatbufferVector<Double> { return _accessor.vector(at: VT.EIGENVALUES_REAL, byteSize: 8) }
  public func withUnsafePointerToEigenvaluesReal<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.EIGENVALUES_REAL, body: body) }
  public var EIGENVALUES_IMAGINARY: FlatbufferVector<Double> { return _accessor.vector(at: VT.EIGENVALUES_IMAGINARY, byteSize: 8) }
  public func withUnsafePointerToEigenvaluesImaginary<T>(_ body: (UnsafeRawBufferPointer, Int) throws -> T) rethrows -> T? { return try _accessor.withUnsafePointerToSlice(at: VT.EIGENVALUES_IMAGINARY, body: body) }
  ///  True when every eigenvalue has a non-positive real part.
  public var STABLE: Bool { let o = _accessor.offset(VT.STABLE); return o == 0 ? false : _accessor.readBuffer(of: Bool.self, at: o) }
  public static func starttbpLibrationPoint(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 8) }
  public static func add(POINT: rfmLibrationPoint, _ fbb: inout FlatBufferBuilder) { fbb.add(element: POINT.rawValue, def: 0, at: VT.POINT) }
  public static func add(X: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: X, def: 0.0, at: VT.X) }
  public static func add(Y: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: Y, def: 0.0, at: VT.Y) }
  public static func add(Z: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: Z, def: 0.0, at: VT.Z) }
  public static func add(JACOBI: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: JACOBI, def: 0.0, at: VT.JACOBI) }
  public static func addVectorOf(EIGENVALUES_REAL: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EIGENVALUES_REAL, at: VT.EIGENVALUES_REAL) }
  public static func addVectorOf(EIGENVALUES_IMAGINARY: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EIGENVALUES_IMAGINARY, at: VT.EIGENVALUES_IMAGINARY) }
  public static func add(STABLE: Bool, _ fbb: inout FlatBufferBuilder) { fbb.add(element: STABLE, def: false,
   at: VT.STABLE) }
  public static func endtbpLibrationPoint(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createtbpLibrationPoint(
    _ fbb: inout FlatBufferBuilder,
    POINT: rfmLibrationPoint = .unspecified,
    X: Double = 0.0,
    Y: Double = 0.0,
    Z: Double = 0.0,
    JACOBI: Double = 0.0,
    EIGENVALUES_REALVectorOffset EIGENVALUES_REAL: Offset = Offset(),
    EIGENVALUES_IMAGINARYVectorOffset EIGENVALUES_IMAGINARY: Offset = Offset(),
    STABLE: Bool = false
  ) -> Offset {
    let __start = tbpLibrationPoint.starttbpLibrationPoint(&fbb)
    tbpLibrationPoint.add(POINT: POINT, &fbb)
    tbpLibrationPoint.add(X: X, &fbb)
    tbpLibrationPoint.add(Y: Y, &fbb)
    tbpLibrationPoint.add(Z: Z, &fbb)
    tbpLibrationPoint.add(JACOBI: JACOBI, &fbb)
    tbpLibrationPoint.addVectorOf(EIGENVALUES_REAL: EIGENVALUES_REAL, &fbb)
    tbpLibrationPoint.addVectorOf(EIGENVALUES_IMAGINARY: EIGENVALUES_IMAGINARY, &fbb)
    tbpLibrationPoint.add(STABLE: STABLE, &fbb)
    return tbpLibrationPoint.endtbpLibrationPoint(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.POINT, fieldName: "POINT", required: false, type: rfmLibrationPoint.self)
    try _v.visit(field: VT.X, fieldName: "X", required: false, type: Double.self)
    try _v.visit(field: VT.Y, fieldName: "Y", required: false, type: Double.self)
    try _v.visit(field: VT.Z, fieldName: "Z", required: false, type: Double.self)
    try _v.visit(field: VT.JACOBI, fieldName: "JACOBI", required: false, type: Double.self)
    try _v.visit(field: VT.EIGENVALUES_REAL, fieldName: "EIGENVALUES_REAL", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.EIGENVALUES_IMAGINARY, fieldName: "EIGENVALUES_IMAGINARY", required: false, type: ForwardOffset<Vector<Double, Double>>.self)
    try _v.visit(field: VT.STABLE, fieldName: "STABLE", required: false, type: Bool.self)
    _v.finish()
  }
}

